PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE SITIOS (
  ID TEXT PRIMARY KEY,
  SLUG TEXT NOT NULL UNIQUE,
  NOMBRE TEXT NOT NULL,
  DOMINIO TEXT NOT NULL UNIQUE,
  TAGLINE TEXT,
  LOGO_URL TEXT,
  FAVICON_URL TEXT,
  TEMPLATE_ID INTEGER DEFAULT 1,
  ACTIVO INTEGER DEFAULT 1
, FACEBOOK_ACTIVO INTEGER DEFAULT 1, FACEBOOK_PAGE_ID TEXT, FACEBOOK_TOKEN_SECRET TEXT);
CREATE TABLE CATEGORIAS (
  ID INTEGER PRIMARY KEY AUTOINCREMENT,
  NOMBRE TEXT NOT NULL,
  SLUG TEXT NOT NULL UNIQUE,
  ACTIVA INTEGER DEFAULT 1
);
CREATE TABLE USUARIOS (ID INTEGER PRIMARY KEY AUTOINCREMENT, NOMBRE TEXT NOT NULL, EMAIL TEXT NOT NULL UNIQUE, PASSWORD_HASH TEXT, ROL TEXT DEFAULT 'editor', ACTIVO INTEGER DEFAULT 1, PASSWORD_SETUP_TOKEN_HASH TEXT, PASSWORD_SETUP_EXPIRES_AT TEXT, PASSWORD_SET_AT TEXT);
CREATE TABLE PASSWORD_RESET_TOKENS (
          ID TEXT PRIMARY KEY,
          USER_ID TEXT NOT NULL,
          TOKEN TEXT UNIQUE NOT NULL,
          EXPIRES_AT TEXT NOT NULL,
          USED INTEGER DEFAULT 0,
          CREATED_AT TEXT NOT NULL
        );
CREATE TABLE WEATHER_DATA (ID INTEGER PRIMARY KEY, CIUDAD TEXT UNIQUE, TEMP INTEGER, CONDICION TEXT, ICONO TEXT, HUMEDAD INTEGER, VIENTO REAL, FECHA_ACTUALIZACION TEXT);
CREATE TABLE IF NOT EXISTS "ARTICULOS_ORIGINALES" (
        ID TEXT PRIMARY KEY,
        TITULO TEXT NOT NULL,
        URL_IMAGEN TEXT,
        FECHA TEXT,
        DESCRIPCION TEXT,
        CONTENIDO TEXT,
        CATEGORIA TEXT,
        LONGITUD INTEGER
      );
CREATE TABLE REVISION_CONTENIDO (
  ID INTEGER PRIMARY KEY AUTOINCREMENT,
  ID_ORIGEN TEXT,
  TIPO_ORIGEN TEXT,
  TITULO_PROPUESTO TEXT,
  CONTENIDO_PROPUESTO TEXT,
  DESCRIPCION_PROPUESTA TEXT,
  SITIO_DESTINO TEXT,
  CATEGORIA TEXT,
  ESTADO TEXT DEFAULT 'PENDIENTE',
  NOTAS_REVISOR TEXT,
  FECHA_PARA_PUBLICAR TEXT,
  FECHA_CREACION TEXT DEFAULT CURRENT_TIMESTAMP,
  URL_IMAGEN TEXT,
  FB_REQUERIDO INTEGER DEFAULT 0,
  ES_BREVE INTEGER DEFAULT 0
);
CREATE TABLE METRICAS_CONTENIDO (
  ID_ARTICULO_PARAFRASEADO TEXT PRIMARY KEY,
  VISTAS INTEGER DEFAULT 0,
  ULTIMA_VISTA TEXT
);
CREATE TABLE LEGALES (
  ID_SITIO TEXT PRIMARY KEY,
  TERMINOS_CONDICIONES TEXT,
  POLITICA_PRIVACIDAD TEXT,
  POLITICA_COOKIES TEXT,
  ACERCA_DE TEXT,
  CONTACTO_EMAIL TEXT,
  CONTACTO_TELEFONO TEXT,
  CONTACTO_DIRECCION TEXT,
  ULTIMA_ACTUALIZACION TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE CANALES_EXTERNOS (
  ID INTEGER PRIMARY KEY AUTOINCREMENT,
  ID_SITIO TEXT,
  TIPO TEXT NOT NULL,
  URL TEXT NOT NULL,
  ETIQUETA TEXT,
  ICONO_CLASE TEXT,
  ORDEN INTEGER DEFAULT 0,
  ACTIVO INTEGER DEFAULT 1
);
CREATE TABLE MENUS_NAVEGACION (
  ID INTEGER PRIMARY KEY AUTOINCREMENT,
  ID_SITIO TEXT,
  ETIQUETA TEXT NOT NULL,
  URL TEXT NOT NULL,
  POSICION TEXT DEFAULT 'HEADER',
  ORDEN INTEGER DEFAULT 0,
  ACTIVO INTEGER DEFAULT 1
);
CREATE TABLE TICKER_FINANCIALS (
  ID INTEGER PRIMARY KEY AUTOINCREMENT,
  SIMBOLO TEXT NOT NULL UNIQUE,
  NOMBRE TEXT NOT NULL,
  VALOR TEXT NOT NULL,
  CAMBIO TEXT DEFAULT '0.00%',
  TENDENCIA TEXT DEFAULT 'up',
  UNIDAD TEXT DEFAULT 'MXN',
  FECHA_ACTUALIZACION TEXT DEFAULT (datetime('now'))
);
CREATE TABLE TICKER_HEADLINES (
  ID INTEGER PRIMARY KEY AUTOINCREMENT,
  TITULO TEXT NOT NULL,
  URL TEXT,
  FUENTE TEXT,
  FECHA_CREACION TEXT DEFAULT (datetime('now'))
);
CREATE TABLE ARTICULOS_PARAFRASEADOS (
  ID TEXT PRIMARY KEY,
  ID_ARTICULO_ORIGINAL TEXT,
  TITULO_PARAFRASEADO TEXT NOT NULL,
  DESCRIPCION_PARAFRASEADA TEXT,
  CONTENIDO TEXT,
  LONGITUD INTEGER,
  SITIO_DESTINO TEXT,
  CATEGORIA TEXT,
  FECHA_PUBLICACION TEXT,
  AUTOR TEXT,
  VERIFICACION TEXT,
  DESTACADO INTEGER DEFAULT 0,
  URL_IMAGEN TEXT,
  SLUG TEXT,
  VISTAS INTEGER DEFAULT 0,
  ESTADO TEXT DEFAULT 'PUBLICADO',
  FB_REQUERIDO INTEGER DEFAULT 0,
  FB_PUBLICADO INTEGER DEFAULT 0,
  FB_FECHA TEXT,
  ES_BREVE INTEGER DEFAULT 0
);
CREATE TABLE ARTICULOS_CMS (
  ID TEXT PRIMARY KEY,
  TITULO TEXT NOT NULL,
  SLUG TEXT NOT NULL UNIQUE,
  DESCRIPCION TEXT,
  CONTENIDO TEXT,
  CATEGORIA TEXT,
  ID_AUTOR INTEGER,
  URL_IMAGEN TEXT,
  SITIOS_DESTINO TEXT,
  ESTADO TEXT DEFAULT 'BORRADOR',
  DESTACADO INTEGER DEFAULT 0,
  FECHA_CREACION TEXT DEFAULT CURRENT_TIMESTAMP,
  FECHA_PUBLICACION TEXT,
  FB_PUBLICADO INTEGER DEFAULT 0,
  FB_FECHA TEXT,
  FB_REQUERIDO INTEGER DEFAULT 0
);
DELETE FROM sqlite_sequence;
